package plan

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

// JSON renders the plan as indented JSON with a trailing newline.
func (p Plan) JSON() ([]byte, error) {
	var b bytes.Buffer
	e := json.NewEncoder(&b)
	e.SetIndent("", "  ")
	if err := e.Encode(p); err != nil {
		return nil, err
	}
	return b.Bytes(), nil
}

// light is for text generated by this program from validated names (titles, scope, table cells).
func light(s string) string {
	return strings.NewReplacer("\r", " ", "\n", " ", "|", "\\|").Replace(s)
}

// esc neutralizes Markdown, HTML and control characters in text that may come from a
// cluster or an API error message.
func esc(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch {
		case r == '\n' || r == '\r' || r == '\t':
			b.WriteByte(' ')
		case r < 0x20 || r == 0x7f:
			b.WriteByte('?')
		case strings.ContainsRune("\\`*_{}[]<>()#+!|~&\"'", r):
			b.WriteByte('\\')
			b.WriteRune(r)
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// fence puts text in a code block that cannot be closed by the text itself.
func fence(lang string, lines []string) string {
	body := strings.Join(lines, "\n")
	f := "```"
	for strings.Contains(body, f) {
		f += "`"
	}
	return f + lang + "\n" + body + "\n" + f + "\n"
}

// Runbook renders RUNBOOK.md: order of operations, maintenance guidance, canary
// strategy, verification and rollback for every step. It is text for humans.
func (p Plan) Runbook() string {
	var b strings.Builder
	fmt.Fprintf(&b, "# cgroup v2 migration runbook (target Kubernetes %s)\n\n", p.Target)
	b.WriteString("> Generated by cgroupguard. **Nothing in this document has been executed.** Read every step, run commands yourself or through your reviewed pipeline, and stop at the first unexpected result.\n\n")
	b.WriteString("## Ground rules\n\n")
	b.WriteString("- Work in an agreed maintenance window with an on-call owner; change one group, verify, soak, then continue.\n")
	b.WriteString("- Every step marked **approval required** must be approved by a named person before it runs.\n")
	b.WriteString("- Never bypass PodDisruptionBudgets (no `--force`, no `--disable-eviction`). Fix the cause of a blocked drain instead.\n")
	b.WriteString("- Each disruptive step lists verification and rollback. If verification fails, roll back before continuing.\n")
	b.WriteString("- Commands use variables (`$CLUSTER_NAME`, `$LOCATION`, `$RESOURCE_GROUP`) that you must set; values that could not be measured are written as `REPLACE_WITH_*` placeholders.\n\n")
	if len(p.Assumptions) > 0 {
		b.WriteString("## Assumptions\n\n")
		for _, a := range p.Assumptions {
			fmt.Fprintf(&b, "- %s\n", esc(a))
		}
		b.WriteString("\n")
	}
	if len(p.Groups) > 0 {
		b.WriteString("## Migration order\n\n| # | Provider | Pool | Nodes | Pods affected | Note |\n|---|---|---|---|---|---|\n")
		for i, g := range p.Groups {
			pods := "unknown"
			if g.Pods != nil {
				pods = fmt.Sprint(*g.Pods)
			}
			note := ""
			if g.Canary {
				note = "canary"
			}
			fmt.Fprintf(&b, "| %d | %s | %s | %d | %s | %s |\n", i+1, light(g.Provider), light(g.Pool), len(g.Nodes), pods, note)
		}
		b.WriteString("\n")
	}
	for _, ph := range p.Phases {
		fmt.Fprintf(&b, "## %s. %s\n\n", ph.ID, light(ph.Title))
		for _, s := range ph.Steps {
			fmt.Fprintf(&b, "### %s — %s\n\n", s.ID, light(s.Title))
			meta := []string{"kind: " + s.Kind, "disruption: " + s.Disruption}
			if s.Approval {
				meta = append(meta, "**approval required**")
			}
			if s.Scope != "" {
				meta = append(meta, "scope: "+light(s.Scope))
			}
			b.WriteString(strings.Join(meta, " · ") + "\n\n")
			if s.Details != "" {
				b.WriteString(s.Details + "\n\n")
			}
			list := func(title string, items []string) {
				if len(items) == 0 {
					return
				}
				b.WriteString("**" + title + "**\n\n")
				for _, it := range items {
					fmt.Fprintf(&b, "- %s\n", it)
				}
				b.WriteString("\n")
			}
			list("Preconditions", s.Preconditions)
			if len(s.Commands) > 0 {
				b.WriteString("**Commands (review, do not paste blindly)**\n\n" + fence("bash", s.Commands) + "\n")
			}
			for _, f := range s.Files {
				fmt.Fprintf(&b, "**File `%s`** (written to the output directory when `--output-dir` is used)\n\n%s\n", f.Path, fence("", strings.Split(strings.TrimRight(f.Content, "\n"), "\n")))
			}
			list("Verify", s.Verification)
			list("Rollback", s.Rollback)
			if len(s.Sources) > 0 {
				b.WriteString("Sources: " + strings.Join(s.Sources, ", ") + "\n\n")
			}
		}
	}
	if len(p.Limitations) > 0 {
		b.WriteString("## Limitations of the scan behind this plan\n\n")
		for _, l := range p.Limitations {
			fmt.Fprintf(&b, "- %s\n", esc(l))
		}
	}
	return b.String()
}
